#!/usr/bin/env python3
"""Offline replay auditor for a small SIP identity boundary (Boundary Profile 1).

Consumes synthetic records from stdin and writes one JSON document to stdout.
It never opens a socket or contacts a SIP service.  Motivated by SIPConfusion
(NDSS 2026): two components can authenticate and display different identities
when they parse or prioritize identity fields differently.  This is a
deliberately constrained defensive model, not a full SIP implementation.
"""

import json
import re
import sys
from collections import deque
from hashlib import sha256

ANON = 'sip:anonymous@anonymous.invalid'
INVALID = object()
MAX_T = 9007199254740991


class Reject(Exception):
    """Event level rejection with a stage reason."""

    def __init__(self, reason):
        Exception.__init__(self, reason)
        self.reason = reason


class EnvelopeError(Exception):
    """The whole input envelope is invalid: exit status 2, no stdout."""


# --------------------------------------------------------------- patterns
_ID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
_HEX_RE = re.compile(r'(?:[0-9A-Fa-f]{2})*\Z')
_BAD_LINE_RE = re.compile(rb'[^\t\x20-\x7e]')
_TOK = r"[A-Za-z0-9\-.!%*_+`'~]"
_TOKEN_RE = re.compile(_TOK + r'+\Z')
_TOKEN_RUN_RE = re.compile(_TOK + r'*')
_DISPLAY_RE = re.compile(r'(?:' + _TOK + r'+[\t ]+)*' + _TOK + r'+[\t ]*\Z')
_QUOTED_RE = re.compile(r'"(?:[\t\x20-\x21\x23-\x5b\x5d-\x7e]|\\[\t\x21-\x7e])*"')
_CALLID_RE = re.compile(r'[A-Za-z0-9_.@\-]{1,64}\Z')
_LABEL_RE = re.compile(r'[A-Za-z0-9](?:[A-Za-z0-9\-]*[A-Za-z0-9])?\Z')
_USER_RUN_RE = re.compile(r"(?:[A-Za-z0-9\-_.!~*'()]|%[0-9A-Fa-f]{2})*")
_HOST_RUN_RE = re.compile(r'[A-Za-z0-9.\-]*')
_DIGIT_RUN_RE = re.compile(r'[0-9]*')
_TEL_RUN_RE = re.compile(r'[0-9().\-]*')
_CSEQ_SPLIT_RE = re.compile(r'[\t ]+')
_ALPHA = frozenset('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz')
_USER_SET = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.!~*'()")
_TEL_DEL = str.maketrans('', '', '-().')
_COMPACT = {'f': 'from', 't': 'to', 'i': 'call-id', 'l': 'content-length'}
_MULTI = frozenset(('p-asserted-identity', 'p-preferred-identity', 'privacy'))
_REQ5 = ('from', 'to', 'call-id', 'content-length', 'cseq')
_DIGITS = frozenset('0123456789')


# ------------------------------------------------------- URI language
def parse_uri_at(s, i):
    """Parse a SIP/SIPS/tel URI starting at s[i].

    Returns (kind, canonical, end_index) or None.  The URI consumes the longest
    prefix matching the grammar; the caller validates the remaining text.
    """
    n = len(s)
    if i >= n:
        return None
    head = s[i:i + 5].lower()
    if head.startswith('sips:'):
        kind = 'sips'
        j = i + 5
    elif head.startswith('sip:'):
        kind = 'sip'
        j = i + 4
    elif head.startswith('tel:'):
        j = i + 4
        if j >= n or s[j] != '+':
            return None
        j += 1
        m = _TEL_RUN_RE.match(s, j)
        raw = s[j:m.end()]
        if not raw:
            return None
        digits = raw.translate(_TEL_DEL)
        ld = len(digits)
        if ld < 3 or ld > 15:
            return None
        if digits[0] not in '123456789':
            return None
        return ('tel', 'tel:+' + digits, m.end())
    else:
        return None
    m = _USER_RUN_RE.match(s, j)
    ue = m.end()
    if ue < n and s[ue] == '%':
        return None                     # malformed percent escape
    if ue >= n or s[ue] != '@':
        return None
    uraw = s[j:ue]
    if '%' in uraw:
        out = []
        k = 0
        ul = len(uraw)
        while k < ul:
            ch = uraw[k]
            if ch == '%':
                dv = int(uraw[k + 1:k + 3], 16)
                if dv > 127:
                    return None
                d = chr(dv)
                if d not in _USER_SET:
                    return None         # escape outside the member set
                out.append(d)
                k += 3
            else:
                out.append(ch)
                k += 1
        user = ''.join(out)
    else:
        user = uraw
    lu = len(user)
    if lu < 1 or lu > 64:
        return None
    j = ue + 1
    m2 = _HOST_RUN_RE.match(s, j)
    he = m2.end()
    host = s[j:he]
    if len(host) < 3 or len(host) > 253:
        return None
    labels = host.split('.')
    if len(labels) < 2:
        return None
    for lab in labels:
        if len(lab) > 63 or not _LABEL_RE.match(lab):
            return None
    if labels[-1][0] not in _ALPHA:
        return None                     # final label begins with a letter
    j = he
    port_txt = None
    if j < n and s[j] == ':':
        j += 1
        m3 = _DIGIT_RUN_RE.match(s, j)
        pe = m3.end()
        pd = s[j:pe]
        if len(pd) < 1 or len(pd) > 5:
            return None
        pv = int(pd)
        if pv < 1 or pv > 65535:
            return None
        port_txt = str(pv)
        j = pe
    canon = kind + ':' + user + '@' + host.lower()
    if port_txt is not None:
        canon = canon + ':' + port_txt
    return (kind, canon, j)


def _bracket(s, k):
    """Parse '<URI>' starting at s[k] == '<'."""
    gt = s.find('>', k + 1)
    if gt < 0:
        return None
    inner = s[k + 1:gt]
    if not inner:
        return None
    if ' ' in inner or '\t' in inner:
        return None                     # no whitespace inside brackets
    r = parse_uri_at(inner, 0)
    if r is None or r[2] != len(inner):
        return None
    return (r[0], r[1], s[gt + 1:])


def parse_address(s):
    """Parse one address from an OWS-stripped string.

    Returns (kind, canonical, rest) or None.
    """
    if not s:
        return None
    if s[0] == '"':
        m = _QUOTED_RE.match(s)
        if not m:
            return None
        k = m.end()
        n = len(s)
        while k < n and (s[k] == ' ' or s[k] == '\t'):
            k += 1
        if k >= n or s[k] != '<':
            return None                 # only SP/HTAB may follow the quote
        return _bracket(s, k)
    lt = s.find('<')
    if lt < 0:
        r = parse_uri_at(s, 0)
        if r is None:
            return None
        return (r[0], r[1], s[r[2]:])
    if lt > 0 and not _DISPLAY_RE.match(s[:lt]):
        return None
    return _bracket(s, lt)


# ------------------------------------------------- field grammar
def parse_from_field(value):
    """From: exactly one address plus exactly one ;tag=TOKEN."""
    r = parse_address(value)
    if r is None:
        return None
    kind, canon, rest = r
    i = 0
    n = len(rest)
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    if i >= n or rest[i] != ';':
        return None
    i += 1
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    if rest[i:i + 3].lower() != 'tag':
        return None
    i += 3
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    if i >= n or rest[i] != '=':
        return None
    i += 1
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    m = _TOKEN_RUN_RE.match(rest, i)
    te = m.end()
    tag = rest[i:te]
    if len(tag) < 1 or len(tag) > 32:
        return None
    if te != n:
        return None                     # no other parameters, no junk
    return (kind, canon, tag)


def parse_cseq(value, method):
    parts = _CSEQ_SPLIT_RE.split(value)
    if len(parts) != 2:
        return None
    num, meth = parts
    ln = len(num)
    if ln < 1 or ln > 10:
        return None
    for ch in num:
        if ch not in _DIGITS:
            return None
    v = int(num)
    if v < 1 or v > 2147483647:
        return None
    if meth != method:
        return None
    return v


def _split_commas(s):
    """Split a header row on commas outside quoted names and angle brackets."""
    if '"' not in s and '<' not in s:
        return s.split(',')
    parts = []
    cur = []
    i = 0
    n = len(s)
    inq = False
    inb = False
    while i < n:
        c = s[i]
        if inq:
            if c == '\\' and i + 1 < n:
                cur.append(c)
                cur.append(s[i + 1])
                i += 2
                continue
            if c == '"':
                inq = False
            cur.append(c)
        elif inb:
            if c == '>':
                inb = False
            cur.append(c)
        else:
            if c == ',':
                parts.append(''.join(cur))
                cur = []
            else:
                if c == '"':
                    inq = True
                elif c == '<':
                    inb = True
                cur.append(c)
        i += 1
    parts.append(''.join(cur))
    return parts


def parse_identity_list(rows):
    """PAI/PPI: None when absent, INVALID on error, else [(kind, canon)]."""
    if rows is None:
        return None
    items = []
    for row in rows:
        for it in _split_commas(row):
            items.append(it.strip(' \t'))
    parsed = []
    for it in items:
        if not it:
            return INVALID               # empty item or empty row
        r = parse_address(it)
        if r is None or r[2] != '':
            return INVALID               # no header parameters
        parsed.append((r[0], r[1]))
    if not parsed or len(parsed) > 2:
        return INVALID
    if len(parsed) == 2:
        if parsed[0][0] == 'tel':
            if parsed[1][0] == 'tel':
                return INVALID
            parsed = [parsed[1], parsed[0]]
        elif parsed[1][0] != 'tel':
            return INVALID               # two SIP/SIPS URIs are invalid
    return parsed


def parse_privacy(rows):
    if rows is None:
        return 'absent'
    val = None
    for row in rows:
        for item in row.split(';'):
            t = item.strip(' \t').lower()
            if t != 'id' and t != 'none':
                return INVALID
            if val is None:
                val = t
            elif val != t:
                return INVALID           # mixing id and none
    if val is None:
        return INVALID
    return val


# ------------------------------------------------- request parsing
def parse_request(data):
    """Decode one SIP request; raises Reject with the proper stage reason."""
    if len(data) > 65536:
        raise Reject('syntax')
    pos = data.find(b'\r\n\r\n')
    if pos < 0:
        raise Reject('syntax')
    hb = data[:pos]
    body = data[pos + 4:]
    if len(hb) > 32768:
        raise Reject('syntax')
    lines = hb.split(b'\r\n')
    if len(lines) > 257:
        raise Reject('syntax')           # start line + at most 256 headers
    for ln in lines:
        if len(ln) > 8192 or _BAD_LINE_RE.search(ln) is not None:
            raise Reject('syntax')
    sl = lines[0].decode('ascii')
    sp = sl.split(' ')
    if len(sp) != 3:
        raise Reject('syntax')
    method = sp[0]
    if method != 'INVITE' and method != 'MESSAGE':
        raise Reject('syntax')
    if sp[2] != 'SIP/2.0':
        raise Reject('syntax')
    r = parse_uri_at(sp[1], 0)
    if r is None or r[0] == 'tel' or r[2] != len(sp[1]):
        raise Reject('syntax')
    target = r[1]
    headers = []
    for k in range(1, len(lines)):
        raw = lines[k].decode('ascii')
        if raw[:1] == ' ' or raw[:1] == '\t':
            if not headers:
                raise Reject('syntax')   # continuation without a header
            nm, val = headers[-1]
            headers[-1] = (nm, val.rstrip(' \t') + ' ' + raw.lstrip(' \t'))
        else:
            ci = raw.find(':')
            if ci < 0:
                raise Reject('syntax')
            nb = raw[:ci].rstrip(' \t')
            if not _TOKEN_RE.match(nb):
                raise Reject('syntax')   # empty or non-token field name
            low = nb.lower()
            headers.append((_COMPACT.get(low, low), raw[ci + 1:]))
    counts = {}
    values = {}
    for nm, val in headers:
        counts[nm] = counts.get(nm, 0) + 1
        v = val.strip(' \t')
        if nm in _MULTI:
            if nm in values:
                values[nm].append(v)
            else:
                values[nm] = [v]
        else:
            values[nm] = v
    for nm in _REQ5:
        if counts.get(nm, 0) != 1:
            raise Reject('headers')
    cl = values['content-length']
    if not cl or len(cl) > 10:
        raise Reject('length')
    for ch in cl:
        if ch not in _DIGITS:
            raise Reject('length')
    if int(cl) != len(body):
        raise Reject('length')
    fr = parse_from_field(values['from'])
    if fr is None:
        raise Reject('fields')
    from_canon = fr[1]
    tag = fr[2]
    tr = parse_address(values['to'])
    if tr is None or tr[2] != '' or tr[0] == 'tel' or tr[1] != target:
        raise Reject('fields')
    call_id = values['call-id']
    if not _CALLID_RE.match(call_id):
        raise Reject('fields')
    cseq = parse_cseq(values['cseq'], method)
    if cseq is None:
        raise Reject('fields')
    pai = parse_identity_list(values.get('p-asserted-identity'))
    if pai is INVALID:
        raise Reject('fields')
    ppi = parse_identity_list(values.get('p-preferred-identity'))
    if ppi is INVALID:
        raise Reject('fields')
    privacy = parse_privacy(values.get('privacy'))
    if privacy is INVALID:
        raise Reject('fields')
    return (method, target, call_id, cseq, from_canon, tag, pai, ppi, privacy,
            body)


# ------------------------------------------------- envelope
def strict_loads(raw):
    if raw[:3] == b'\xef\xbb\xbf':
        raise EnvelopeError('bom')
    text = raw.decode('utf-8')           # strict: rejects malformed UTF-8

    def no_const(_x):
        raise EnvelopeError('non-finite number')

    def no_float(_x):
        raise EnvelopeError('fractional or exponent number')

    def pairs(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise EnvelopeError('duplicate object key')
            d[k] = v
        return d

    return json.loads(text, object_pairs_hook=pairs, parse_constant=no_const,
                      parse_float=no_float)


def _exact_keys(obj, keys):
    if not isinstance(obj, dict):
        raise EnvelopeError('not an object')
    if set(obj.keys()) != keys:
        raise EnvelopeError('key set')
    return obj


def _int_field(v, lo, hi):
    if type(v) is not int:               # excludes bool and non-integers
        raise EnvelopeError('integer')
    if v < lo or v > hi:
        raise EnvelopeError('integer range')
    return v


def validate_envelope(doc):
    _exact_keys(doc, frozenset(('version', 'config', 'events')))
    if type(doc['version']) is not int or doc['version'] != 1:
        raise EnvelopeError('version')
    cfg = _exact_keys(doc['config'],
                      frozenset(('accounts', 'peers', 'ttl_ms', 'capacity')))
    accounts = cfg['accounts']
    if not isinstance(accounts, list) or len(accounts) > 256:
        raise EnvelopeError('accounts')
    acct_ids = set()
    alias_owner = {}
    acct_default = {}
    for a in accounts:
        _exact_keys(a, frozenset(('id', 'default', 'aliases')))
        aid = a['id']
        if not isinstance(aid, str) or not _ID_RE.match(aid) or aid in acct_ids:
            raise EnvelopeError('account id')
        acct_ids.add(aid)
        aliases = a['aliases']
        if not isinstance(aliases, list) or len(aliases) < 1 or len(aliases) > 8:
            raise EnvelopeError('aliases')
        seen = set()
        for al in aliases:
            if not isinstance(al, str):
                raise EnvelopeError('alias type')
            r = parse_uri_at(al, 0)
            if r is None or r[2] != len(al) or r[1] != al:
                raise EnvelopeError('alias not canonical')
            if r[1] == ANON:
                raise EnvelopeError('anonymous alias')
            if al in seen or al in alias_owner:
                raise EnvelopeError('alias ownership')
            seen.add(al)
            alias_owner[al] = aid
        dflt = a['default']
        if not isinstance(dflt, str) or dflt not in seen:
            raise EnvelopeError('default alias')
        acct_default[aid] = dflt
    peers = cfg['peers']
    if not isinstance(peers, list) or len(peers) < 1 or len(peers) > 256:
        raise EnvelopeError('peers')
    peer_ids = set()
    peer_info = {}
    for p in peers:
        _exact_keys(p, frozenset(('id', 'mode', 'accounts')))
        pid = p['id']
        if not isinstance(pid, str) or not _ID_RE.match(pid) or pid in peer_ids:
            raise EnvelopeError('peer id')
        peer_ids.add(pid)
        mode = p['mode']
        if mode == 'access':
            if p['accounts'] != []:
                raise EnvelopeError('access peer accounts')
            allowed = frozenset()
        elif mode == 'relay':
            pac = p['accounts']
            if not isinstance(pac, list):
                raise EnvelopeError('relay accounts type')
            if len(set(pac)) != len(pac):
                raise EnvelopeError('relay accounts distinct')
            for x in pac:
                if not isinstance(x, str) or x not in acct_ids:
                    raise EnvelopeError('relay account id')
            allowed = frozenset(pac)
        else:
            raise EnvelopeError('peer mode')
        peer_info[pid] = (mode, allowed)
    ttl = _int_field(cfg['ttl_ms'], 1, 1000000)
    cap = _int_field(cfg['capacity'], 1, 10000)
    events = doc['events']
    if not isinstance(events, list) or len(events) > 10000:
        raise EnvelopeError('events')
    ev_list = []
    prev_t = None
    for e in events:
        _exact_keys(e, frozenset(('t', 'peer', 'auth', 'egress', 'wire_hex')))
        t = _int_field(e['t'], 0, MAX_T)
        if prev_t is not None and t < prev_t:
            raise EnvelopeError('descending time')
        prev_t = t
        pid = e['peer']
        if not isinstance(pid, str) or pid not in peer_ids:
            raise EnvelopeError('peer id')
        auth = e['auth']
        if auth is not None:
            if not isinstance(auth, str) or auth not in acct_ids:
                raise EnvelopeError('auth id')
        if peer_info[pid][0] == 'relay' and auth is not None:
            raise EnvelopeError('relay auth')
        eg = e['egress']
        if eg != 'internal' and eg != 'external':
            raise EnvelopeError('egress')
        wh = e['wire_hex']
        if not isinstance(wh, str) or len(wh) > 131072:
            raise EnvelopeError('wire_hex')
        ev_list.append((t, pid, auth, eg, wh))
    return acct_default, alias_owner, peer_info, ttl, cap, ev_list


# ------------------------------------------------- policy
def apply_policy(mode, allowed, auth, pai, ppi, privacy, from_canon,
                 acct_default, alias_owner):
    """Sections 4 and 6-7: returns (account, identity, asserted list)."""
    if mode == 'access':
        if ppi is not None:
            for _k, u in ppi:
                if alias_owner.get(u) != auth:
                    raise Reject('identity')
            asserted = [u for _k, u in ppi]
            identity = asserted[0]
        else:
            identity = acct_default[auth]
            asserted = [identity]
        acct = auth
    else:
        if ppi is not None:
            raise Reject('identity')     # PPI must be absent on a relay
        if pai is None:
            raise Reject('identity')     # PAI must be present on a relay
        owner = None
        for _k, u in pai:
            o = alias_owner.get(u)
            if o is None:
                raise Reject('identity')
            if owner is None:
                owner = o
            elif owner != o:
                raise Reject('identity')
        if owner not in allowed:
            raise Reject('identity')
        acct = owner
        asserted = [u for _k, u in pai]
        identity = asserted[0]
    if alias_owner.get(from_canon) != acct:
        if from_canon != ANON or privacy != 'id':
            raise Reject('identity')
    return acct, identity, asserted


# ------------------------------------------------- main
def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        return 2
    try:
        doc = strict_loads(raw)
    except Exception:
        return 2
    del raw
    try:
        acct_default, alias_owner, peer_info, ttl, cap, ev_list = \
            validate_envelope(doc)
    except EnvelopeError:
        return 2
    del doc

    results = []
    accepted = 0
    replayed = 0
    rejected = 0
    ledger = {}
    order = deque()                      # (key, insert time), insertion order

    for idx, (t, pid, auth, eg, wh) in enumerate(ev_list):
        # Section 5: expire before processing every event.
        while order and order[0][1] + ttl <= t:
            ledger.pop(order.popleft()[0], None)
        mode, allowed = peer_info[pid]
        try:
            if not _HEX_RE.match(wh):
                raise Reject('hex')
            data = bytes.fromhex(wh)
            (method, target, call_id, cseq, from_canon, tag, pai, ppi,
             privacy, body) = parse_request(data)
            if mode == 'access' and auth is None:
                raise Reject('auth')
            acct, identity, asserted = apply_policy(
                mode, allowed, auth, pai, ppi, privacy, from_canon,
                acct_default, alias_owner)
        except Reject as rej:
            results.append({'index': idx, 'decision': 'reject',
                            'reason': rej.reason})
            rejected += 1
            continue
        # Normalized outgoing projection.
        if privacy == 'id':
            out_from = ANON
        else:
            out_from = identity
        if eg == 'external' and privacy != 'none':
            out_pai = []
        else:
            out_pai = list(asserted)
        digest = sha256(body).digest()
        key = (pid, call_id, cseq, method)
        commit = (acct, identity, tuple(asserted), from_canon, tag, target,
                  privacy, eg, digest)
        ent = ledger.get(key)
        if ent is None:
            if len(ledger) >= cap:
                ledger.pop(order.popleft()[0], None)
            ledger[key] = (idx, t, commit)
            order.append((key, t))
            accepted += 1
            first = idx
            decision = 'accept'
        elif ent[2] == commit:
            replayed += 1
            first = ent[0]
            decision = 'replay'
        else:
            results.append({'index': idx, 'decision': 'reject',
                            'reason': 'conflict'})
            rejected += 1
            continue
        results.append({
            'index': idx,
            'decision': decision,
            'first': first,
            'account': acct,
            'identity': identity,
            'from': out_from,
            'pai': out_pai,
            'method': method,
            'target': target,
            'call_id': call_id,
            'cseq': cseq,
            'tag': tag,
            'privacy': privacy,
            'body_sha256': digest.hex(),
        })

    out = {'results': results, 'accepted': accepted, 'replayed': replayed,
           'rejected': rejected, 'live': len(ledger)}
    sys.stdout.write(json.dumps(out))
    sys.stdout.write('\n')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
